window.__sheets=[]; window.__toasts=[]; window.__seenSheet=false;
const seenT=new Set();
new MutationObserver(()=>{
  const s=document.querySelector('.ui-choice');
  if(s&&!window.__seenSheet){window.__seenSheet=true;window.__sheets.push(s.querySelector('h2,[class*=title]')?.textContent||s.textContent.slice(0,30));}
  if(!s) window.__seenSheet=false;
  for(const t of document.querySelectorAll('.ui-toast-text')){const k=t.textContent;if(!seenT.has(k+window.__sheets.length+window.__toasts.length)){}}
}).observe(document.body,{childList:true,subtree:true});
true;
